<script setup lang="ts">
import {t as tr} from "../i18n";
import {ref,onMounted,watch} from 'vue';import {businessApi,useBusinessStore} from '../stores/business';import type {Notice} from '@shared/mobile';import type {Target} from '@shared/labops-targets.js';import AsyncState from './AsyncState.vue';import {useVisibleRefresh} from '../composables/useVisibleRefresh';
const props=defineProps<{noticeId?:string}>(),emit=defineEmits<{navigate:[Target];changed:[]}>(),business=useBusinessStore(),items=ref<Notice[]>([]),detail=ref<Notice>(),loading=ref(true),busy=ref(false),error=ref('');let generation=0;
async function refresh(){const epoch=++generation;try{if(props.noticeId){const result=await businessApi<{notification:Notice}>('proxy/notifications/'+encodeURIComponent(props.noticeId));if(epoch!==generation)return;detail.value=result.notification;if(!detail.value.readAt)await read(detail.value);}else{const result=await businessApi<{notifications:Notice[]}>('proxy/notifications?limit=100');if(epoch!==generation)return;items.value=result.notifications.reverse();}error.value='';}catch(e){if(epoch===generation)error.value=(e as Error).message;}finally{loading.value=false;}}
async function read(notice:Notice){const result=await businessApi<{id:string;readAt:string}>('proxy/notifications/read',{id:notice.id,scopeKey:business.scopeKey});notice.readAt=result.readAt;emit('changed');}
async function allRead(){if(busy.value)return;busy.value=true;error.value='';try{const unread=items.value.filter(n=>!n.readAt),failed:string[]=[];for(let i=0;i<unread.length;i+=50){const result=await businessApi<{results:Array<{id:string;ok:boolean;readAt?:string;message?:string}>}>('proxy/notifications/read-batch',{ids:unread.slice(i,i+50).map(n=>n.id),scopeKey:business.scopeKey});for(const item of result.results){if(item.ok){const n=items.value.find(n=>n.id===item.id);if(n)n.readAt=item.readAt||null;}else failed.push(item.id);}}emit('changed');if(failed.length)throw new Error(failed.length+' 条通知未确认已读，已保留未读标记');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(refresh);watch(()=>props.noticeId,()=>{detail.value=undefined;loading.value=true;void refresh();});useVisibleRefresh(refresh,()=>!busy.value);
</script>
<template><AsyncState :loading="loading" :error="error" @retry="refresh"><template v-if="!noticeId"><div class="mobile-actions"><span>{{tr("本人未读")}} {{items.filter(n=>!n.readAt).length}}</span><button :disabled="busy||!items.some(n=>!n.readAt)" @click="allRead">{{tr("全部标记已读")}}</button></div><p v-if="!items.length" class="mobile-state">{{tr("当前没有本人可见的通知。")}}</p><button v-for="n in items" :key="n.id" class="mobile-row mobile-notice" @click="emit('navigate',{view:'notice',noticeId:n.id})"><b>{{n.title}}</b><span>{{tr(n.readAt?'已读':'未读')}} · {{new Date(n.time).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</span><small>{{n.content.slice(0,100)}}</small></button></template><article v-else-if="detail" class="mobile-section"><h2>{{detail.title}}</h2><p>{{tr(detail.readAt?'服务端已确认已读':'正在确认已读')}} · {{detail.time}}</p><div class="mobile-formal">{{detail.content}}</div><p class="mobile-source">{{tr("通知")}} {{detail.id}} {{tr("· 本人读取")}} {{tr(detail.readAt||'尚未确认')}}</p><button v-if="detail.scheduledJobId" @click="emit('navigate',{view:'job',jobId:detail.scheduledJobId})">{{tr("查看关联规则与执行记录")}}</button><button v-if="detail.target" @click="emit('navigate',detail.target)">{{tr("前往关联事项")}}</button></article></AsyncState></template>
